package com.ias.ticket;
import com.ias.trust.*;
import jakarta.servlet.http.HttpServletRequest;
import org.springframework.web.bind.annotation.*;
import java.sql.Timestamp;
import java.time.*;
import java.util.*;

@RestController
public class Reopens {
 final Tickets t;final StaffAccess access;
 public Reopens(Tickets t,StaffAccess access){this.t=t;this.access=access;}
 static Problem conflict(String code){return new Problem(409,code);}
 Tickets.Actor customer(HttpServletRequest r){Chain.source(r);long deadline=Chain.deadline(r);String token=Chain.cookie(r),csrf=r.getHeader("X-CSRF-TOKEN");var f=Chain.identity("ticket-identity",token,"TICKET_CUSTOMER_REOPEN",csrf,Chain.trace(r),deadline);Chain.fresh(f,deadline);return new Tickets.Actor(Tickets.id(f.get("tenantId")),Tickets.id(f.get("userId")),f.get("identityType").toString(),token,csrf,Chain.trace(r),deadline,f.get("attempt").toString());}
 void reporter(Tickets.Actor a,Map<String,Object>row){if(!a.type().equals("CUSTOMER")||Tickets.id(row.get("reporter_user_id"))!=a.user())throw new Problem(404,"TARGET_NOT_ACCESSIBLE");t.accessible(row.get("id").toString(),a);}
 Map<String,Object> closure(Object ticket,Object round,Object operation){var rows=t.db.queryForList("SELECT c.*,a.department_id source_department_id FROM ticket_closure c JOIN ticket_solution s ON s.id=c.solution_id AND s.round_id=c.round_id JOIN ticket_assignment a ON a.id=s.assignment_id AND a.round_id=c.round_id WHERE c.ticket_id=? AND c.round_id=?",ticket,round);if(rows.isEmpty()||operation!=null&&!rows.getFirst().get("operation_id").equals(operation))throw conflict("SOURCE_CLOSURE_CONFLICT");return rows.getFirst();}
 boolean reviewable(Map<String,Object>facts,Map<String,Object>row,Map<String,Object>closed){return Boolean.TRUE.equals(facts.get("enabled"))&&Boolean.TRUE.equals(facts.get("departmentEnabled"))&&access.company(facts,row.get("company_id"))&&access.permission(facts,"ticket.reopen.review")&&((List<?>)facts.get("reopenReviewDepartmentIds")).contains(closed.get("source_department_id").toString());}
 void reviewer(Tickets.Actor a,Map<String,Object>row,Map<String,Object>closed){if(!a.type().equals("EMPLOYEE"))throw new Problem(403,"ACCESS_DENIED");if(!reviewable(access.facts(a),row,closed))throw new Problem(403,"ACCESS_DENIED");}
 Map<String,Object> current(Map<String,Object>row){if(row.get("current_reopen_id")==null)return null;return request(row.get("current_reopen_id"));}
 Map<String,Object> request(Object id){var rows=t.db.queryForList("SELECT * FROM ticket_reopen_request WHERE id=?",id);if(rows.isEmpty())throw new Problem(404,"TARGET_NOT_ACCESSIBLE");return rows.getFirst();}
 Map<String,Object> end(Object id){var rows=t.db.queryForList("SELECT * FROM ticket_reopen_decision WHERE request_id=?",id);return rows.isEmpty()?null:rows.getFirst();}
 Instant now(){return new Completion(t,access).now();}
 static boolean inWindow(Instant closed,Instant requested){return !requested.isBefore(closed)&&!requested.isAfter(closed.plus(Duration.ofHours(168)));}
 Map<String,Object> check(Map<String,Object>row,Tickets.Actor a){reporter(a,row);var out=new LinkedHashMap<String,Object>();out.put("ticketId",row.get("id"));out.put("sourceRoundId",row.get("round_id"));Instant time=now();out.put("serverNow",time.toString());var blockers=new ArrayList<String>();Map<String,Object>closed=null;if(!"CLOSED".equals(row.get("status")))blockers.add("INVALID_STATE");else try{closed=closure(row.get("id"),row.get("round_id"),null);}catch(Problem e){blockers.add(e.code);}out.put("sourceClosureOperationId",closed==null?null:closed.get("operation_id"));out.put("closedAt",closed==null?null:Tickets.utc(closed.get("closed_at")));out.put("reopenDeadline",closed==null?null:Completion.instant(closed.get("closed_at")).plus(Duration.ofHours(168)).toString());if(closed!=null&&!inWindow(Completion.instant(closed.get("closed_at")),time))blockers.add("REOPEN_WINDOW_CLOSED");if(row.get("current_reopen_id")!=null)blockers.add("REOPEN_PENDING");if(!new Completion(t,access).supported(row))blockers.add("UNSUPPORTED_RELATED_BUSINESS");out.put("canRequest",blockers.isEmpty());out.put("blockers",blockers);return out;}
 @GetMapping("/api/ticket/tickets/{id}/reopen-check") Map<String,Object> check(@PathVariable String id,HttpServletRequest r){if(!r.getParameterMap().isEmpty())throw Tickets.bad();var a=t.actor(r,false);return check(t.accessible(id,a),a);}
 Map<String,Object> input(Map<String,Object>b,boolean decision){var expected=new HashSet<>(Set.of("expectedVersion","sourceRoundId","sourceClosureOperationId","reason"));if(decision){expected.add("decision");if("APPROVE".equals(b.get("decision"))){expected.addAll(Set.of("sameFault","priority"));if(b.containsKey("targetDepartmentId")||b.containsKey("targetEngineerUserId"))expected.addAll(Set.of("targetDepartmentId","targetEngineerUserId"));if(!Boolean.TRUE.equals(b.get("sameFault"))||!(b.get("priority") instanceof String)||!Set.of("P1","P2","P3").contains(b.get("priority")))throw Tickets.bad();}else if(!"REJECT".equals(b.get("decision")))throw Tickets.bad();}if(!b.keySet().equals(expected))throw Tickets.bad();var out=new TreeMap<String,Object>(b);for(String k:List.of("expectedVersion","targetDepartmentId","targetEngineerUserId"))if(out.containsKey(k)){if(!(out.get(k) instanceof String))throw Tickets.bad();out.put(k,Long.toString(Tickets.id(out.get(k))));}Tickets.uuid(out.get("sourceRoundId"));Tickets.uuid(out.get("sourceClosureOperationId"));Tickets.text(out.get("reason"),5,500,true);return out;}
 @PostMapping("/api/ticket/tickets/{id}/reopen-requests") Map<String,Object> apply(@PathVariable String id,@RequestBody Map<String,Object>b,HttpServletRequest r){return perform(id,null,input(b,false),customer(r),Tickets.uuid(Chain.single(r,"Idempotency-Key")));}
 @PostMapping("/api/ticket/tickets/{id}/reopen-requests/{request}/decision") Map<String,Object> decide(@PathVariable String id,@PathVariable String request,@RequestBody Map<String,Object>b,HttpServletRequest r){var data=input(b,true);data.put("reopenRequestId",Tickets.uuid(request));return perform(id,request,data,new Workflow(t,access).actor(r),Tickets.uuid(Chain.single(r,"Idempotency-Key")));}
 Map<String,Object> perform(String id,String requestedId,Map<String,Object>b,Tickets.Actor a,String op){return performAt(id,requestedId,b,a,op,null);}
 public Map<String,Object> performAt(String id,String requestedId,Map<String,Object>b,Tickets.Actor a,String op,Instant observedAt){Tickets.uuid(id);t.accessible(id,a);String digest=Tickets.hash(b);return t.tx.execute(tx->{
  String request=requestedId; t.lockActor(a.tenant(),a.user());var row=t.db.queryForMap("SELECT * FROM ticket_record WHERE id=? AND tenant_id=? FOR UPDATE",id,a.tenant());Chain.fresh(Chain.identity("ticket-identity",a.token(),request==null?"TICKET_CUSTOMER_REOPEN":"TICKET_WORK",a.csrf(),a.trace(),a.deadline()),a.deadline());t.accessible(id,a);
  Map<String,Object>q=request==null?null:request(request);Map<String,Object>closed;
  if(request==null){reporter(a,row);closed=null;}else{if(!q.get("ticket_id").equals(id))throw new Problem(404,"TARGET_NOT_ACCESSIBLE");closed=closure(id,q.get("source_round_id"),q.get("source_closure_operation_id"));reviewer(a,row,closed);if(Tickets.id(q.get("requested_by"))==a.user())throw new Problem(403,"ACCESS_DENIED");}
  var prior=t.db.queryForList("SELECT * FROM ticket_action_operation WHERE operation_id=? FOR UPDATE",op);if(!prior.isEmpty()){var old=prior.getFirst();if(Tickets.id(old.get("tenant_id"))!=a.tenant()||Tickets.id(old.get("actor_user_id"))!=a.user()||!id.equals(old.get("ticket_id")))throw new Problem(404,"OPERATION_NOT_FOUND");if(!digest.equals(old.get("request_digest"))||!old.get("action").equals(request==null?"reopen-request":"reopen-decision"))throw conflict("IDEMPOTENCY_CONFLICT");return Tickets.json(old.get("result_json"));}
  FeePartPermitBarrier.guard(t,id);if(!row.get("round_id").equals(b.get("sourceRoundId")))throw conflict("ROUND_CONFLICT");if(Tickets.id(row.get("row_version"))!=Tickets.id(b.get("expectedVersion"))||Tickets.id(row.get("row_version"))==Long.MAX_VALUE)throw conflict("VERSION_CONFLICT");Workflow.state(row.get("status").toString(),"CLOSED");new Completion(t,access).requireSupported(row);closed=closure(id,b.get("sourceRoundId"),b.get("sourceClosureOperationId"));
  if(row.get("assignment_id")!=null)t.db.queryForList("SELECT id FROM ticket_assignment WHERE id=? FOR UPDATE",row.get("assignment_id"));t.db.queryForList("SELECT operation_id FROM ticket_closure WHERE ticket_id=? AND round_id=? FOR UPDATE",id,row.get("round_id"));Instant time=observedAt==null?now():observedAt;String record=UUID.randomUUID().toString(),action=request==null?"reopen-request":"reopen-decision",state,next="CLOSED",newRound=null,newAssignment=null;Map<String,Object>rule=null;
  if(request==null){if(row.get("current_reopen_id")!=null)throw conflict("REOPEN_PENDING");Instant closedAt=Completion.instant(closed.get("closed_at"));if(!inWindow(closedAt,time))throw conflict("REOPEN_WINDOW_CLOSED");request=UUID.randomUUID().toString();t.db.update("INSERT INTO ticket_reopen_request(id,ticket_id,source_round_id,source_closure_operation_id,operation_id,requested_by,reason,requested_at,reopen_deadline) VALUES(?,?,?,?,?,?,?,?,?)",request,id,row.get("round_id"),closed.get("operation_id"),op,a.user(),b.get("reason"),Timestamp.from(time),Timestamp.from(closedAt.plus(Duration.ofHours(168))));t.db.update("UPDATE ticket_record SET current_reopen_id=? WHERE id=?",request,id);q=request(request);state="PENDING_REVIEW";}
  else{if(!Objects.equals(row.get("current_reopen_id"),request)||end(request)!=null||!q.get("source_round_id").equals(b.get("sourceRoundId"))||!q.get("source_closure_operation_id").equals(b.get("sourceClosureOperationId")))throw conflict("REOPEN_NOT_CURRENT");t.db.queryForList("SELECT id FROM ticket_reopen_request WHERE id=? FOR UPDATE",request);boolean approved="APPROVE".equals(b.get("decision"));state=approved?"APPROVED":"REJECTED";
   if(approved){if(b.containsKey("targetEngineerUserId")){var facts=access.facts(a);access.department(facts,b.get("targetDepartmentId"));var proof=Chain.call("ticket-identity","/internal/identity/ticket-authorizations",Map.of("sessionToken",a.token(),"purpose","REOPEN","departmentId",b.get("targetDepartmentId"),"targetUserId",b.get("targetEngineerUserId")),a.trace(),a.deadline());Chain.fresh(proof,a.deadline());if(!Boolean.TRUE.equals(proof.get("eligible")))throw conflict("TARGET_INELIGIBLE");}
    var rounds=new Rounds(t);rounds.freeze(row,Completion.instant(closed.get("closed_at")));var meta=rounds.metadata(row);int number=((Number)meta.get("round_no")).intValue();if(number==Integer.MAX_VALUE)throw conflict("ROUND_CONFLICT");newRound=UUID.randomUUID().toString();rule=Rounds.activeRule();rounds.insert(newRound,id,number+1,"REOPEN_APPROVAL",time,a.user(),row.get("round_id"),closed.get("operation_id"),request,op,b.get("priority").toString(),rule);next=b.containsKey("targetEngineerUserId")?"ASSIGNED":"WAITING_ASSIGNMENT";
    t.db.update("UPDATE ticket_record SET assignment_id=NULL,department_id=NULL,engineer_user_id=NULL,current_solution_id=NULL,current_supplement_id=NULL,current_cancel_request_id=NULL,current_transfer_id=NULL,current_reopen_id=NULL WHERE id=?",id);
    t.db.update("UPDATE ticket_record SET round_id=?,round_started_at=?,initial_priority=?,priority=?,priority_source='REOPEN_APPROVAL',priority_rule_version='REOPEN_MANUAL_V1',policy_version=?,first_response_at=NULL,first_response_actor=NULL,first_response_record_id=NULL,first_response_priority=NULL,response_due_at=?,resolution_due_at=? WHERE id=?",newRound,Timestamp.from(time),b.get("priority"),b.get("priority"),rule.get("version"),Timestamp.from(time.plusSeconds(Rounds.limit(rule,"responseMinutes",b.get("priority"))*60)),Timestamp.from(time.plusSeconds(Rounds.limit(rule,"resolutionHours",b.get("priority"))*3600)),id);
    t.db.update("INSERT INTO ticket_sla_target_history(ticket_id,round_id,operation_id,new_priority,reason,submitted_at,response_due_at,resolution_due_at,policy_version,created_at) SELECT id,round_id,?,priority,?,round_started_at,response_due_at,resolution_due_at,policy_version,? FROM ticket_record WHERE id=?",op,b.get("reason"),Timestamp.from(time),id);if(b.containsKey("targetEngineerUserId")){newAssignment=UUID.randomUUID().toString();t.db.update("INSERT INTO ticket_assignment(id,ticket_id,round_id,tenant_id,department_id,engineer_user_id,assigned_by,note,created_at) VALUES(?,?,?,?,?,?,?,?,?)",newAssignment,id,newRound,a.tenant(),Tickets.id(b.get("targetDepartmentId")),Tickets.id(b.get("targetEngineerUserId")),a.user(),"REOPEN_APPROVAL",Timestamp.from(time));t.db.update("UPDATE ticket_record SET assignment_id=?,department_id=?,engineer_user_id=? WHERE id=?",newAssignment,Tickets.id(b.get("targetDepartmentId")),Tickets.id(b.get("targetEngineerUserId")),id);}
   }else t.db.update("UPDATE ticket_record SET current_reopen_id=NULL WHERE id=?",id);
   t.db.update("INSERT INTO ticket_reopen_decision(request_id,ticket_id,operation_id,decision,reason,decided_by,decided_at,new_round_id,priority) VALUES(?,?,?,?,?,?,?,?,?)",request,id,op,b.get("decision"),b.get("reason"),a.user(),Timestamp.from(time),newRound,approved?b.get("priority"):null);
  }
  var out=new LinkedHashMap<String,Object>();out.putAll(Map.of("operationId",op,"action",action,"state",state,"ticketId",id,"reopenRequestId",request,"sourceRoundId",b.get("sourceRoundId"),"sourceClosureOperationId",b.get("sourceClosureOperationId"),"status",next,"rowVersion",Long.toString(Tickets.id(row.get("row_version"))+1),"recordId",record));out.put("requestedAt",Tickets.utc(q.get("requested_at")));out.put("reopenDeadline",Tickets.utc(q.get("reopen_deadline")));out.put("newRoundId",newRound);out.put("assignmentId",newAssignment);out.put("roundStartedAt",newRound==null?null:time.toString());out.put("sla",rule==null?null:rule);String writeRound=newRound==null?row.get("round_id").toString():newRound;
  t.db.update("UPDATE ticket_record SET status=?,row_version=row_version+1 WHERE id=?",next,id);write(row,a.user(),op,action,digest,out,record,writeRound,newRound==null?row.get("assignment_id"):newAssignment,b.get("reason").toString(),time);Chain.remaining(a.deadline());return out;
 });}
 void write(Map<String,Object>row,long actor,String op,String action,String digest,Map<String,Object>out,String record,Object round,Object assignment,String body,Instant time){t.db.update("INSERT INTO ticket_processing_record(id,ticket_id,round_id,assignment_id,operation_id,actor_user_id,type,body,work_hours,visibility,qualification_json,row_version,occurred_at) VALUES(?,?,?,?,?,?,?,?,0,'CUSTOMER_VISIBLE','{}',?,?)",record,row.get("id"),round,assignment,op,actor,action.toUpperCase(Locale.ROOT).replace('-','_'),body,out.get("rowVersion"),Timestamp.from(time));t.db.update("INSERT INTO ticket_action_operation(operation_id,tenant_id,actor_user_id,ticket_id,action,request_digest,result_json,created_at) VALUES(?,?,?,?,?,?,?,?)",op,row.get("tenant_id"),actor,row.get("id"),action,digest,Chain.JSON.writeValueAsString(out),Timestamp.from(time));t.db.update("INSERT INTO ticket_audit(operation_id,tenant_id,actor_user_id,action,occurred_at) VALUES(?,?,?,?,?)",op,row.get("tenant_id"),actor,"WORKFLOW_"+action.toUpperCase(Locale.ROOT).replace('-','_'),Timestamp.from(time));}
 @PostMapping("/api/ticket/tickets/{id}/rounds/{round}/responses") Map<String,Object> respond(@PathVariable String id,@PathVariable String round,@RequestBody Map<String,Object>b,HttpServletRequest r){if(!b.keySet().equals(Set.of("expectedVersion","body"))||!(b.get("expectedVersion") instanceof String))throw Tickets.bad();Tickets.id(b.get("expectedVersion"));Tickets.text(b.get("body"),5,2000,true);var data=new TreeMap<String,Object>(b);data.put("roundId",Tickets.uuid(round));return response(id,data,new Workflow(t,access).actor(r),Tickets.uuid(Chain.single(r,"Idempotency-Key")));}
 boolean mayRespond(Map<String,Object>f,Map<String,Object>row){String state=row.get("status").toString();return Set.of("WAITING_ASSIGNMENT","ASSIGNED","IN_PROGRESS").contains(state)&&(access.company(f,row.get("company_id"))&&access.permission(f,"ticket.respond")||state.equals("IN_PROGRESS")&&access.engineer(f,row)&&access.permission(f,"ticket.record"));}
 Map<String,Object> response(String id,Map<String,Object>b,Tickets.Actor a,String op){t.accessible(id,a);return t.tx.execute(tx->{t.lockActor(a.tenant(),a.user());var row=t.db.queryForMap("SELECT * FROM ticket_record WHERE id=? AND tenant_id=? FOR UPDATE",id,a.tenant());Chain.fresh(Chain.identity("ticket-identity",a.token(),"TICKET_WORK",a.csrf(),a.trace(),a.deadline()),a.deadline());t.accessible(id,a);var f=access.facts(a);boolean role=access.company(f,row.get("company_id"))&&access.permission(f,"ticket.respond")||access.engineer(f,row)&&access.permission(f,"ticket.record");if(!role)throw new Problem(403,"ACCESS_DENIED");String digest=Tickets.hash(b);var old=t.db.queryForList("SELECT * FROM ticket_action_operation WHERE operation_id=? FOR UPDATE",op);if(!old.isEmpty()){var p=old.getFirst();if(Tickets.id(p.get("actor_user_id"))!=a.user()||Tickets.id(p.get("tenant_id"))!=a.tenant()||!id.equals(p.get("ticket_id")))throw new Problem(404,"OPERATION_NOT_FOUND");if(!"round-response".equals(p.get("action"))||!digest.equals(p.get("request_digest")))throw conflict("IDEMPOTENCY_CONFLICT");return Tickets.json(p.get("result_json"));}if(!row.get("round_id").equals(b.get("roundId")))throw conflict("ROUND_CONFLICT");if(Tickets.id(row.get("row_version"))!=Tickets.id(b.get("expectedVersion"))||Tickets.id(row.get("row_version"))==Long.MAX_VALUE)throw conflict("VERSION_CONFLICT");if(!mayRespond(f,row))throw conflict("INVALID_STATE");String record=UUID.randomUUID().toString();Instant time=now();boolean first=new Rounds(t).first(row,a,record,time,op);t.db.update("UPDATE ticket_record SET row_version=row_version+1 WHERE id=?",id);var out=new LinkedHashMap<String,Object>(Map.of("operationId",op,"action","round-response","state","COMPLETED","ticketId",id,"roundId",b.get("roundId"),"recordId",record,"rowVersion",Long.toString(Tickets.id(row.get("row_version"))+1),"status",row.get("status"),"firstResponse",first));out.put("firstResponseAt",first?time.toString():Tickets.utc(row.get("first_response_at")));write(row,a.user(),op,"round-response",digest,out,record,row.get("round_id"),row.get("assignment_id"),b.get("body").toString(),time);Chain.remaining(a.deadline());return out;});}
 Map<String,Object> view(Map<String,Object>q){var out=new LinkedHashMap<String,Object>();out.putAll(Map.of("reopenRequestId",q.get("id"),"ticketId",q.get("ticket_id"),"sourceRoundId",q.get("source_round_id"),"sourceClosureOperationId",q.get("source_closure_operation_id"),"requestedBy",q.get("requested_by").toString(),"requestedAt",Tickets.utc(q.get("requested_at")),"reopenDeadline",Tickets.utc(q.get("reopen_deadline")),"reason",q.get("reason")));var e=end(q.get("id"));out.put("state",e==null?"PENDING_REVIEW":e.get("decision").equals("APPROVE")?"APPROVED":"REJECTED");if(e==null)out.put("decision",null);else{var d=new LinkedHashMap<String,Object>();for(String[]p:new String[][]{{"decision","decision"},{"reason","reason"},{"newRoundId","new_round_id"},{"priority","priority"}})d.put(p[0],e.get(p[1]));d.put("decidedBy",e.get("decided_by").toString());d.put("decidedAt",Tickets.utc(e.get("decided_at")));out.put("decision",d);}return out;}
 void project(Map<String,Object>out,Map<String,Object>row,Tickets.Actor a){var q=current(row);out.put("currentReopen",q==null?null:view(q));var actions=new ArrayList<String>((List<String>)out.get("allowedActions"));if(a.type().equals("CUSTOMER")){if(Boolean.TRUE.equals(check(row,a).get("canRequest")))actions.add("reopen-request");}else{var f=access.facts(a);if(mayRespond(f,row))actions.add("round-response");boolean can=false;if("CLOSED".equals(row.get("status")))can=reviewable(f,row,closure(row.get("id"),row.get("round_id"),null));if(q!=null&&can)actions.add("reopen-review");out.put("reopenReviewDepartments",can?f.get("reopenReviewDepartments"):List.of());out.put("reopenAssignableDepartments",can?f.get("assignableDepartments"):List.of());}out.put("allowedActions",actions);}
 @GetMapping("/api/ticket/tickets/{id}/reopen-requests") Map<String,Object> history(@PathVariable String id,HttpServletRequest r){var a=t.actor(r,false);t.accessible(id,a);var p=Transfers.page(r,Set.of("page","size"));return Map.of("items",t.db.queryForList("SELECT * FROM ticket_reopen_request WHERE ticket_id=? ORDER BY requested_at DESC,id DESC LIMIT ? OFFSET ?",id,p[1],(p[0]-1)*p[1]).stream().map(this::view).toList(),"total",t.db.queryForObject("SELECT COUNT(*) FROM ticket_reopen_request WHERE ticket_id=?",Long.class,id),"page",p[0],"size",p[1]);}
 @GetMapping("/api/ticket/tickets/{id}/reopen-candidates") Map<String,Object> candidates(@PathVariable String id,HttpServletRequest r){var a=t.actor(r,false);var row=t.accessible(id,a);Workflow.state(row.get("status").toString(),"CLOSED");reviewer(a,row,closure(id,row.get("round_id"),null));Transfers.page(r,Set.of("departmentId","keyword","page","size"));String dept=Long.toString(Tickets.id(r.getParameter("departmentId")));access.department(access.facts(a),dept);var body=new HashMap<String,Object>();body.putAll(Map.of("sessionToken",a.token(),"purpose","REOPEN","departmentId",dept));for(String key:List.of("page","size","keyword"))if(r.getParameter(key)!=null)body.put(key,r.getParameter(key));var out=Chain.call("ticket-identity","/internal/identity/ticket-candidates",body,a.trace(),a.deadline());Chain.fresh(out,a.deadline());return out;}
 Map<String,Object> queue(String where,List<Object>args,Tickets.Actor a,long page,long size){var f=access.facts(a);if(!access.permission(f,"ticket.reopen.review")||!Boolean.TRUE.equals(f.get("departmentEnabled")))throw new Problem(403,"ACCESS_DENIED");var departments=(List<?>)f.get("reopenReviewDepartmentIds");if(departments.isEmpty())where+=" AND 1=0";else{where+=" AND r.current_reopen_id IS NOT NULL AND EXISTS(SELECT 1 FROM ticket_closure c JOIN ticket_solution s ON s.id=c.solution_id JOIN ticket_assignment ass ON ass.id=s.assignment_id WHERE c.ticket_id=r.id AND c.round_id=r.round_id AND ass.department_id IN ("+String.join(",",Collections.nCopies(departments.size(),"?"))+"))";departments.forEach(d->args.add(Tickets.id(d)));}where+=" AND r.status='CLOSED'";var c=(List<?>)f.get("companyIds");if(!access.permission(f,"ticket.read")||c.isEmpty())where+=" AND 1=0";else{where+=" AND r.company_id IN ("+String.join(",",Collections.nCopies(c.size(),"?"))+")";c.forEach(v->args.add(Tickets.id(v)));}long total=t.db.queryForObject("SELECT COUNT(*) FROM ticket_record r WHERE "+where,Long.class,args.toArray());var values=new ArrayList<>(args);values.add(size);values.add((page-1)*size);return Map.of("items",t.db.queryForList("SELECT r.* FROM ticket_record r WHERE "+where+" ORDER BY r.submitted_at,r.id LIMIT ? OFFSET ?",values.toArray()).stream().map(row->{var out=t.summary(row);out.put("currentReopen",view(current(row)));return out;}).toList(),"total",total,"page",page,"size",size);}
}
